var L={H:"Handle",R:"Route / warm transfer",S:"Stop: don’t answer, document, warm transfer"};
var CATS=["Claims","Payments & Reinstatement","Cancellations","General Service"];
var D=[
{id:"fnol",c:0,l:"R",t:"Report a new claim (FNOL)",k:"fnol first notice of loss new claim report loss ccrf",s:"Insured calls to report a loss. Capture facts only, log it, then warm transfer: carrier if there are no licensed questions or concerns, licensed team if there are.",
f:["End of intake: no licensed questions or concerns, warm transfer to the carrier. Licensed questions or concerns, warm transfer to the licensed team.","Capture: date, time, location, type of loss, objective description (caller’s words), parties, injuries yes/no, police report, current condition.","Select client: complete the FNOL and route the caller to the carrier. Signature client: route to the P&C Claims name on the account (Servicing tab) if there is one, otherwise the Account Manager (P&C Servicer 1).","Workers’ Comp or Professional / Management Liability: route to the P&C Claims name on the account (Servicing tab) if there is one, otherwise the Account Manager (P&C Servicer 1).","Auto, Property and GL FNOLs are assigned to the *CCLP workgroup.","Check Epic for an existing open claim first so no duplicate is created.","Do not collect full SSNs or detailed medical information.","Client wants to send documents: email ClaimInformation_CL@Acrisure.com.","Locate the account by business or client name, phone number or business/mailing address.","Auto section also asks for a description of vehicle damage; use “Other / Additional Loss Information” for anything that doesn’t fit."],
p:["Verify the caller (two identifiers).","Account Details > Servicing > check Client Service Segment.","Complete the FNOL form (no fault, coverage or liability language).","Decide the transfer: no licensed questions or concerns go to the carrier; licensed questions or concerns go to the licensed team.","Policies > highlight policy > F9 (or New > Activity).","Activity Code: CCRF (this is the FNOL activity).","Priority Urgent; Owner *CCLP; attach the FNOL.","Note: received call from (name), completed FNOL attached, call transferred to [carrier or licensed team]."],
q:[["Opening","I’m sorry to hear about the incident. Let me make sure this is logged correctly and that you have the right contact. Could I take your policy number and a brief description of what happened?"],["Offer","The fastest way to get an adjuster assigned is to report it to the carrier. I can take the first notice of loss and warm transfer you to them. Would you like me to do that?"],["Missing info","I can document the information available now, and the carrier or account team may follow up if more details are needed."],["Closing","I’ve logged the claim details on your account and noted everything in our system. The carrier will take the full details and open the claim directly. Is there anything else I can help you with right now?"],["Duplicate claim","It looks like a claim for this loss is already open under [number]. Let’s work from that rather than create a duplicate. Here’s where it stands."],["Sending documents","Please email any claim documents or photos to ClaimInformation_CL@Acrisure.com."],["Transfer to carrier","I’ve documented your information. I’m going to connect you to the carrier now so they can take the full details and open the claim. Please hold."],["Transfer to licensed team","That is a licensed question, so I’m going to connect you with the appropriate licensed team member. I’ve documented your information so you won’t need to repeat it. Please hold."]],
n:["Never write fault, liability or causation language, even the caller’s own.","Never say the loss will be covered."],e:"CCRF"},
{id:"emergency",c:0,l:"R",t:"Emergency, injury or after-hours loss",k:"emergency 911 injury after hours fire water in progress 24/7",s:"The loss is happening now or someone is hurt. Safety first, then a warm transfer to the carrier’s claims line.",
f:["Ask about safety before anything else.","Outside business hours, warm transfer to the carrier’s claims line first, then offer next-business-day follow-up.","Log the FNOL and document the callback commitment."],p:["Confirm everyone is safe; 911 if needed.","Warm transfer to the carrier’s claims line.","Log FNOL (CCRF) and commit to follow up."],
q:[["Safety","First, is everyone safe, and is anyone hurt? If this is an emergency or someone is injured, make sure 911 has been called before we do anything else."],["Carrier line","Because this is happening right now, the fastest path is a warm transfer to the carrier’s claims line. They can assign an adjuster immediately. I’ll follow up on the file first thing tomorrow so nothing sits."],["After hours","Our office is closed, but I can connect you to the carrier’s claims line right now and they can assign an adjuster tonight. I’d do that now rather than wait, and I’ll pick it up on our end in the morning."],["Safety first","Safety first. Make sure everyone is safe and 911 is called if needed. The claim can wait until people are taken care of."]],n:["Do not leave claim details in voicemail."],e:"CCRF"},
{id:"claim-status",c:0,l:"H",t:"Claim status",k:"claim status update adjuster open claim",s:"Share only verified status from Epic/ACLM or the carrier record.",
f:["Verified facts only: claim number, adjuster, stage on record, documents received.","Stop point: don’t answer a request to interpret coverage, merit or next steps. Document it, then warm transfer.","Warm transfer preferred when escalating."],p:["Verify caller.","Check ACLM activity / carrier record.","Give the status; offer to reach out to the adjuster."],
q:[["Status","I can confirm the factual claim status we have on file. Your claim number is [X] and the assigned adjuster is [name]. They have the most current status."],["If asked what it means","The question about whether that means coverage applies is a licensed coverage question, so I’m going to connect you with the appropriate licensed team member."],["Stalled claim","Let me get on this. I’ll contact the adjuster directly today and note the urgency on the file so someone gets back to you with a real update."],["Claim closed","I can confirm the claim is showing as closed on [date] with the information on the carrier record. Questions about whether the settlement was appropriate or whether a claim can be reopened need to be reviewed by the licensed Acrisure team."]],n:["Do not say the carrier agrees it is covered."],e:"ACLM / CCRF"},
{id:"coverage-q",c:0,l:"S",t:"“Will this be covered?” / “Will the carrier pay?”",k:"coverage covered pay payout settle licensed stop",s:"Stop point: don’t answer. Document it, then warm transfer to the licensed team.",
f:["Never interpret coverage, exclusions, liability, negligence or expected outcome.","If unsure whether a question needs a license, do not answer: document it and transfer."],p:["Acknowledge.","Use approved transfer language.","Warm transfer and brief the licensed team."],
q:[["Approved","That is a licensed coverage question, so I am going to connect you with the appropriate licensed team member."],["Outcome","The carrier will review the claim and determine next steps. I can document what you shared and route it to the appropriate team."],["Won’t guess","I understand wanting to know, and I won’t guess and risk getting it wrong. Coverage on a specific loss is the adjuster’s determination after review."],["Payout estimate","Only the adjuster’s review confirms coverage and the amount on this loss. I don’t want you relying on a guess, so let’s get it in front of them."]],n:["“This should be covered.”","“The carrier will pay this.”"],e:"CCRF"},
{id:"premium-impact",c:0,l:"S",t:"“Will this raise my premium or affect the audit?”",k:"premium impact increase audit renewal claim",s:"Stop point: don’t answer. Never say a claim will or will not affect premium or audit. Document it, then warm transfer to the licensed team.",
f:["Premium and audit impact is a licensed / underwriting judgment."],p:["Acknowledge.","Document the question.","Route to licensed team."],
q:[["Approved","Premium impact questions need to be reviewed by the licensed Acrisure team. I can document the question and connect you with the appropriate team."],["Audit","That ties to how the claim resolves and to underwriting, so I’ll have a licensed agent walk you through what to expect rather than give you a number that could change."]],n:["“This will not impact your premium.”"],e:"CCRF"},
{id:"legal",c:0,l:"S",t:"Lawsuit, demand letter or attorney",k:"lawsuit litigation attorney demand letter summons served legal",s:"Document the trigger, escalate the same day, never discuss legal strategy.",
f:["Document: type of document, date received, sender, response deadline.","Attorney calls: name, law firm, contact information, representation letter.","Automatic escalation: litigation, fatality, estimated loss $100k or more, Workers’ Comp.","Tell the insured not to communicate with the other side until the carrier’s counsel is involved."],p:["Document trigger, date/time, caller, claim and documents.","Set CCRF to Urgent; owner the appropriate team (CCL workgroup) or the Account Manager per escalation rules.","Same-day route."],
q:[["Demand letter","I will document that a demand letter has been received and route this to the appropriate team. I cannot advise on legal handling, but I will make sure the right team receives the information."],["Served","This is urgent because there are response deadlines. I’m routing it to the adjuster and an agent right now."]],n:["Never advise on legal strategy or attorney handling."],e:"CCRF (Urgent)"},
{id:"claimant",c:0,l:"R",t:"Third party or claimant calling",k:"third party claimant not client opposing party",s:"Collect their contact and incident details; disclose nothing about the insured.",
f:["Do not release claim details, policy limits, coverage status or insured contact information.","Claims can only be filed at the request of the client.","Third-party callers are escalated to the P&C Claims name on the account (Servicing tab) if there is one, otherwise the Account Manager (P&C Servicer 1)."],p:["Confirm caller is not an authorized contact.","Take name, phone and facts.","Log CCRF and route."],
q:[["Script","Thank you for calling. I’m sorry to hear about the incident. Could I take your name, phone number and the details of what happened? Unfortunately, we can only file claims at the request of the client."],["Close","I’ve logged the details and will have someone reach out to our client."]],n:["Never disclose insured policy details."],e:"CCRF"},
{id:"file-or-not",c:0,l:"S",t:"“Should I file a claim?”",k:"should file report claim reopen dispute",s:"Never recommend filing, reopening or disputing. Lay out the process and route.",
f:["Firm exceptions to state: any workplace injury, any incident that could become a third-party claim or lawsuit, cyber incidents and employee complaints should be reported.","Document the inquiry and outcome, including a decision not to report."],p:["Do not suggest an option.","Name the licensed agent as the advisor.","Document."],
q:[["Approved","I can document the information available now and connect you with the right team or carrier contact for next steps."],["Reopen/dispute","Questions about reopening or disputing a claim need to be reviewed by the licensed Acrisure team."]],n:["“You should file the claim.”","“You can reopen the claim.”"],e:"CCRF"},
{id:"pay-info",c:1,l:"H",t:"Next due date, balance or invoice copy",k:"due date balance invoice copy amount due payment history",s:"Verified billing facts you may share, then hand off for payment.",
f:["Check policy Stage: Issued or Submitted continue; Cancelled or In-Process do not continue, escalate via CBIQ to P&C Servicer 1.","Bill type: D = direct bill (carrier); A = agency bill. “Y” in Financed column = IPFS or First Insurance Funding.","Direct bill: use LastPass vault, open the carrier portal, MFA code via Outlook/Teams, billing section.","Invoice copy: save from the portal and email it. Get the caller’s email first.","Separate current premium from any audit balance."],p:["Verify caller.","Segment check (Signature stops and routes to P&C Servicer 1).","Policy status check, then bill type.","Provide facts; warm transfer for payment (agency: P&C Servicer 1; direct: carrier, number from LastPass).","Document CBIQ."],
q:[["Balance","I can see the amount currently showing as due is [amount], with a due date of [date]. For payment support, I can transfer you to the carrier billing department."],["Invoice","Can you please provide the email address where the document should be sent?"]],n:["Do not discuss anything the caller isn’t verified for."],e:"CBIQ"},
{id:"make-payment",c:1,l:"R",t:"Make a payment",k:"pay payment make e-pay epay link carrier portal financed ipfs fif agency bill direct bill",s:"Reps don’t take payments. Route by bill type.",
f:["Direct bill: look up the carrier’s number in LastPass (shared Global Service Team vault) and warm transfer to the carrier. Don’t give the number to the caller.","Agency bill: warm transfer to P&C Servicer 1 for payment.","Agency bill, financed: check the signed PFA under Access > Attachments to find the lender, then email the finance portal link (IPFS or FIF).","Questions about the invoice or finance payment: P&C Servicer 1.","Never read full card or account numbers aloud (PCI)."],p:["Check Stage and bill type.","Direct: find the number in LastPass and warm transfer to the carrier. Agency: warm transfer to P&C Servicer 1. Financed: finance portal link.","Document CBIQ."],
q:[["Direct bill","I can transfer you to the carrier’s billing department so the payment can be taken securely."],["Agency bill","I’ll connect you with our servicing team who can help you with the payment. Please hold."],["Recap","Thank you for calling. Today I have [action] to support your billing inquiry. Is there anything else I can do for you? Thank you for being an Acrisure client."],["Can’t pay in full","Payment options, including any plan or revised due date, need to be reviewed directly with the billing department. I can transfer you now."],["Payer not authorized","I can direct your payment toward the account. I can’t share policy details without authorization, but I can point you to the right payment option."],["Finance company","This policy is financed, so I’ll email you the finance company’s payment link. Can you please provide the email address where it should be sent?"]],n:["Don’t promise payment will keep coverage in force."],e:"CBIQ"},
{id:"pending-cancel",c:1,l:"R",t:"Past due or pending cancellation notice",k:"past due grace period pending cancellation notice noc deadline",s:"State the factual deadline and transfer for payment. Don’t guarantee the outcome.",
f:["Confirm the notice date from the attachment in Epic or the carrier site.","Advise payment must be received by the deadline to avoid cancellation.","Past due: advise paying immediately to keep coverage active (agency bill: warm transfer to P&C Servicer 1; direct bill: find the carrier number in LastPass and warm transfer)."],p:["Verify and check status.","State deadline.","Warm transfer (agency: P&C Servicer 1; direct: carrier, number from LastPass).","Document CBIQ."],
q:[["Past due","I see the payment is past due, and the policy has not yet been cancelled. The deadline showing is [date]. I can transfer you to the carrier billing department for payment assistance."],["Pending","I see a pending cancellation date of [date]. I cannot guarantee the outcome, but I can transfer you so payment options can be reviewed directly."],["Agency bill","I see a pending cancellation date of [date]. I’ll connect you with our servicing team so they can help with the payment. Please hold."]],n:["Don’t say “you’re set, no lapse”."],e:"CBIQ"},
{id:"reinstatement",c:1,l:"S",t:"Policy cancelled: reinstatement",k:"reinstate reinstatement lapsed cancelled non-payment statement of no loss",s:"Reinstatement is the carrier’s decision. Document and route to P&C Servicer 1.",
f:["Advise that the Account Manager can request reinstatement from the carrier.","Create an EPIC activity and assign it to P&C Servicer 1.","Don’t discuss eligibility, amounts needed or likelihood of approval.","Statement of No Loss: do not explain, validate, collect or advise.","Claims-made policy lapses can affect prior-acts coverage: route immediately.","Beyond the reinstatement window it is likely a new application: licensed agent.","Document the call in Epic using the Epic notes guide (status, dates, concern, safe expectation statement, routing, action)."],p:["Verify and confirm cancellation in Epic or carrier site.","State facts, then stop.","Create activity, urgent, owner P&C Servicer 1.","Document."],
q:[["Approved","Because the policy shows cancelled as of [date], this becomes a reinstatement-related question. I will document what you shared and route you to the appropriate licensed or carrier representative."],["Guarantee","I don’t want to guarantee something that requires carrier approval."],["SNL","That is tied to a reinstatement review, so I am not able to advise on or collect that. I will document your request and route it to the appropriate licensed path."],["Account Manager","Reinstatement is a carrier decision. Your Account Manager can request it from the carrier, so I’ll document your request and assign it to them now."],["Lender or certificates","I understand the concern. I cannot confirm coverage or certificate validity after a lapse, but I will document the details and route this to the appropriate team."],["Claims-made","Because this involves a claims-made policy and a possible lapse, I need to route this for licensed review. I will document the concern clearly."]],n:["Never promise reinstatement.","Never confirm coverage after a lapse."],e:"CBIQ (Urgent)"},
{id:"audit",c:1,l:"R",t:"Audit balance or audit dispute",k:"audit balance dispute payroll final audit",s:"You may separate current premium from the audit balance. Disputes go to P&C Servicer 1.",
f:["Audit: the carrier’s review to confirm the information used to calculate premium was accurate.","Current premium is ongoing billing; audit balance is a prior-period adjustment.","Audit balances can still be owed after cancellation."],p:["State what is visible.","Don’t resolve or advise.","Route to P&C Servicer 1; document."],
q:[["Script","I can document that you are questioning the audit balance. Audit disputes must be reviewed through the appropriate account or licensed path, so I will route this for follow-up."]],n:["Never guarantee audit results."],e:"CBIQ"},
{id:"noc",c:2,l:"R",t:"Carrier notice of cancellation received",k:"noc notice of cancellation carrier cancel ccn1 non-compliance confused",s:"Lead with empathy, collect the facts, warm transfer to licensed team. Use CCN1 for non-compliance notices; CCN2 for non-payment.",
f:["Capture: policy reference, notice status (for example grace period), effective date, caller concern.","If the effective date is within about 5 business days, treat as urgent.","Never confirm or deny coverage status.","CCN1 = carrier notice for non-compliance (underwriting, inspection, audit). CCN2 = non-payment. CCN3 = client requested cancel."],p:["Verify.","Get policy number and dates.","Warm transfer to licensed team.","Document with the correct CCN code."],
q:[["Open","I completely understand your concern. Receiving a notice like that can be unsettling. Let me connect you with the right person who can give you an accurate answer. Could I take your policy number?"],["Close","I’m connecting you now with our licensed team who will explain what this means and the next steps. I’ve noted your policy reference and the effective date. Please hold."],["Urgent","Because the effective date is close, I’m going to route this as a priority and include your callback information in the note."],["Lender needs proof","I can document the lienholder request and route it to the appropriate team. I don’t want to provide coverage confirmation until the policy information has been reviewed."]],n:["Don’t explain reasons for the carrier’s action."],e:"CCN1"},
{id:"noc-nonpay",c:2,l:"R",t:"Carrier notice of cancellation for non-payment",k:"noc notice of cancellation non-payment nonpayment ccn2 pending cancel past due",s:"Lead with empathy, state the factual deadline if visible, warm transfer or route for payment. Don’t guarantee the outcome.",
f:["Capture: policy reference, notice status, effective date, caller concern.","If the effective date is within about 5 business days, treat as urgent.","Never confirm or deny coverage status.","Activity code CCN2 for non-payment notices (Direct Bill or Premium Finance)."],p:["Verify.","Get policy number and dates.","State deadline if known.","Warm transfer for payment or route to licensed team.","Document CCN2."],
q:[["Open","I completely understand your concern. Receiving a notice like that can be unsettling. Let me connect you with the right person who can give you an accurate answer. Could I take your policy number?"],["Past due","I see a notice related to non-payment. The deadline showing is [date]. I can transfer you so payment options can be reviewed directly."],["Close","I’m connecting you now with the team who will explain what this means and the next steps. I’ve noted your policy reference and the effective date. Please hold."]],n:["Don’t explain reasons for the carrier’s action.","Don’t say “you’re set, no lapse”."],e:"CCN2"},
{id:"cancel-req",c:2,l:"R",t:"Insured wants to cancel",k:"cancel request cancellation replacement coverage retention new carrier business sold closed ccn3",s:"Receive the request, gather facts, route to licensed team. Don’t treat it as confirmed.",
f:["Verify: policy, carrier, effective date, reason, replacement coverage date.","Ask: “Do you already have replacement coverage bound?” to prevent a lapse and protect the business.","Cancellation can cause: coverage gaps, contract breaches, uninsured claim exposure, certificate and lender issues (force-placed), audit balances owed.","Retention flags: moving carrier, premium increase, service dissatisfaction, claim concerns.","Background only: removing one policy can change discounts or package pricing. Don’t say that to callers.","Activity code CCN3 – Client Request for Cancellation (*CCCR). Owner: P&C Servicer 1."],p:["Verify.","Gather facts (reason, effective date requested, replacement coverage).","Create CCN3 activity, assign to P&C Servicer 1.","Document and route.","Commit to a callback if needed."],
q:[["Open","I can help make sure this is directed to the right person. Could I take your policy number and confirm the coverage you’d like to discuss?"],["Replacement","I can document that you are requesting cancellation and that replacement coverage may be involved. The licensed team needs to review the cancellation terms and effective date before this is finalized."],["Close","I’m connecting you now with our licensed team, who will walk you through the process, including any return premium and the effective date."],["Refund question","Refund amounts and return premium calculations need to be reviewed through the appropriate process. I can document your refund question and route it for follow-up."],["Reason for cancelling","May I ask what’s prompting the request? I’ll note it so whoever you speak with is fully prepared and you won’t need to repeat yourself."]],n:["Never quote return premium or refund timing."],e:"CCN3"},
{id:"gap",c:2,l:"S",t:"“Do I still have coverage?” / “Will there be a gap?”",k:"coverage gap still have coverage lapse lienholder proof refund",s:"Acknowledge, don’t debate, route as priority.",
f:["Never confirm or deny coverage status, return premium, gap risk or reinstatement eligibility.","Lienholder needs proof: don’t confirm coverage; document and route promptly.","Refund question: document and route."],p:["Acknowledge urgency.","Priority route with effective date and callback in the note.","Same-day callback if no licensed agent is available."],
q:[["Coverage","I understand why you are asking. I cannot confirm coverage status, but I can document the concern and connect you with the licensed team who can review it accurately."],["Gap","Coverage gap questions require licensed review. I am going to route this as a priority and include the effective date and your callback information."],["Why can’t you","I want to make sure you receive accurate information. These questions can affect coverage, refund or policy terms, so they need to be reviewed by the licensed team."]],n:["Don’t quote refunds."],e:"GCAL"},
{id:"csc-claim",c:0,l:"R",t:"Claim on a Carrier Service Center policy",k:"carrier service center servicer 2 email forward warm transfer split servicing claim",s:"P&C Servicer 2 shows a Carrier Service Center, so the carrier services that policy. Forward by email or warm transfer.",
f:["Check P&C Servicer 2 at account level, then confirm at policy level (policy > Servicing Contacts). A person’s name or blank means NOT carrier serviced.","Never assume all policies on an account have the same servicing responsibility.","Email subject line: insured name and policy number. Copy the insured. Ask the Carrier Service Center to request any other information from the insured. Attach the FNOL if completed."],p:["Verify and confirm servicing at policy level.","Email or warm transfer to the carrier.","Create the CCRF activity and attach the email.","Note: FNOL and claim email sent to (carrier email) to report and gather further details from the insured.","Assign to *CCLP for monitoring."],
q:[["Handoff","I’ll connect you with the carrier’s service center, who can take the full details and open the claim directly."]],n:["Don’t promise how the carrier will handle the claim."],e:"CCRF"},
{id:"large-loss",c:0,l:"R",t:"Large loss or significant reserve increase",k:"large loss reserve increase severity escalation 100k fatality workers comp",s:"Document the facts and escalate. Never comment on reserve adequacy or strategy.",
f:["Automatic escalation: estimated loss $100,000 or more, litigation or lawsuit, fatality, Workers’ Comp, Professional / Management Liability.","Escalate the completed FNOL to the P&C Claims name on the account (Servicing tab) if there is one, otherwise the Account Manager (P&C Servicer 1).","Document: factual severity, injuries or unsafe conditions, affected operations, carrier information, reserve change as stated."],p:["Complete FNOL and note the trigger.","Create CCRF; Urgent; owner per escalation rules.","Same-day route."],
q:[["Reserve update","I can update the activity with the factual reserve information and note this as an escalation trigger. Any questions about reserve adequacy or claim strategy should be reviewed by the licensed team."]],n:["Never explain what a reserve means for the claim."],e:"CCRF (Urgent)"},
{id:"callback",c:3,l:"H",t:"Callbacks and voicemail privacy",k:"callback voicemail privacy recorded monitored message leave message",s:"Schedule callbacks safely and never leave claim details in a voicemail.",
f:["Confirm callback name, number, email, preferred time and timeframe; document the commitment.","Use a privacy-safe voicemail with no claim details.","Callback opening should include the monitoring and recording statement."],p:["Confirm callback details.","Document in Epic.","Use the privacy-safe script."],
q:[["Callback opening","This call is being monitored or recorded for quality and training purposes."],["Voicemail","Hello, this is [Name] calling from Acrisure regarding your recent request. Please call us back at [number]. Thank you."]],n:["Never leave claim details in voicemail."],e:"GCAL"},
{id:"unclear",c:3,l:"S",t:"Unclear question: don’t know if it needs a license",k:"unclear unsure not sure licensed question do not answer transfer",s:"When in doubt, don’t answer.",
f:["Do not answer.","Document the exact question and transfer to the licensed team."],p:["Write the caller’s exact words.","Warm transfer; brief the licensed team."],
q:[["Script","That’s an important question. Let me connect you with a licensed agent who can review your specific situation."]],n:["Never guess."],e:"GCAL"},
{id:"wc-injury",c:0,l:"R",t:"Workplace injury (Workers’ Comp)",k:"workers comp injury employee injured work accident report wait and see",s:"Report right away. Deadlines are set by state, so when in doubt report the same day.",f:["Capture: employee name, date and time of injury, what happened, body part affected, whether treatment was sought.","An injured employee reporting their own injury is not an authorized account contact, but take the report and let the employer’s contact on file know a report was filed.","Don’t discuss the company’s policy details with the employee.","Workers’ Comp routes to P&C Servicer 1."],p:["Take the report from whoever is calling.","Complete the FNOL, facts only.","Create the activity and route to P&C Servicer 1.","Give the claim number if available."],q:[["Report now","For a workplace injury, we want to report this right away. Workers’ comp has strict timeframes, and prompt reporting protects both the employee and the business. Let me capture the basics and get this to the carrier."],["Employee calling","I can take the injury report from you directly. That’s important enough that we don’t want it waiting. I won’t be able to discuss the company’s policy details with you, but the claim itself I can absolutely start."],["Wait and see","I understand, but workers’ comp injuries should be reported promptly even if they seem minor. Delayed reporting can hurt the employee’s benefits and the business’s compliance."]],n:["Never use fault language.","Don’t discuss benefits or outcomes."],e:"CCRF"},
{id:"property-loss",c:0,l:"R",t:"Property loss and repairs",k:"property damage business interruption repairs photos mitigation receipts",s:"Document, log, and remind the caller to protect the property and keep records.",f:["Ask whether the property is secured (yes, no, unknown).","Reinforce: prevent further damage, keep receipts, photograph before repairs.","The adjuster inspects the loss."],p:["Complete the property section of the FNOL.","Warm transfer to the carrier to report the claim.","Document the advice given."],q:[["Start repairs","Protect the property from further damage and keep receipts. Before permanent repairs, document everything with photos and let the adjuster inspect, or it can complicate the claim."],["Next steps","I’ll get the claim reported so an adjuster can inspect."]],n:["Don’t say what will be paid."],e:"CCRF"},
{id:"cyber-epli",c:0,l:"R",t:"Cyber incident or employment practices complaint",k:"cyber breach ransomware epli eeoc employment complaint attorney notice",s:"Time-sensitive notice items. Report the same day and route to a licensed agent.",f:["Cyber: short notice windows; the carrier’s incident response team should be engaged first.","Employment practices: an agency charge, complaint or attorney letter counts as a claim; late notice can jeopardize coverage.","Preserve systems and logs; don’t respond to the other side."],p:["Report immediately.","Route to adjuster and licensed agent.","Document the trigger and dates."],q:[["Cyber","This needs to go to the carrier today. Cyber policies have short notice requirements, and most provide an incident response team that should be engaged before you bring in your own IT vendor. Please preserve the systems and logs rather than wiping anything."],["Employment complaint","Even at this stage that counts as a claim, and late notice can jeopardize it. Let me report it now and route you to the adjuster and a licensed agent. Please don’t respond to the complaint or the attorney until the carrier’s counsel is engaged."]],n:["Don’t downplay the incident."],e:"CCRF (Urgent)"},
{id:"upset",c:3,l:"H",t:"Upset or distressed caller",k:"upset angry frustrated distressed empathy complaint why cant you",s:"Acknowledge, stay calm, restate the next step.",f:["Lead with empathy; don’t debate.","Restate the reason for routing without arguing.","Client dissatisfaction is an escalation trigger."],p:["Acknowledge.","Explain what you can do.","Route and document."],q:[["Empathy","I hear you, and I’m sorry. This is a lot to deal with. Let’s take it one step at a time; I’ll stay with you and make sure you know exactly what happens next."],["Why can’t you","I want to make sure you receive accurate information. These questions can affect coverage, refund, or policy terms, so they need to be reviewed by the licensed team."],["Reassure","I’m sorry to hear that happened. I’ll make sure the information is documented clearly and routed to the right team."]],n:["“Don’t worry, this will be handled.”"],e:"GCAL"},
{id:"verify",c:3,l:"H",t:"Caller verification and third parties",k:"verify authentication authorization identifiers third party dissatisfied unauthorized",s:"Verify before disclosing anything.",
f:["Greet: “Thank you for calling Acrisure. This is [name]. How may I assist you?”","Verify: ask for the business name and the mailing address, then who you’re speaking with and their role with the business. The caller provides these; don’t read them out of Epic. Other identifiers: business phone, policy number.","Third party: must provide business name, line of business and policy number. If verified you may provide effective dates, status or a declarations page.","Unsuccessful or dissatisfied: no policy-specific information. Document the reason and email; route to the Account Manager.","Authorized: owner, officer, designated contact. Limited: bookkeepers, third-party payers, admin staff."],p:["Locate in Epic.","Ask for identifiers.","Branch: successful, unsuccessful, third party, dissatisfied.","Document GCAL."],
q:[["Greeting","Thank you for calling Acrisure. This is [name]. How may I assist you?"],["Verify business","May I know the business name and the mailing address?"],["Verify caller","Great, and who am I speaking with and your role with [Business Name]?"],["Unsuccessful","I was unable to successfully verify your account. Can you please provide the reason for your call?"],["Limited access","I can only share account details with an authorized contact."],["Not an authorized contact","I can share general information on how claims work, but for details on a specific claim I’ll need an owner, officer, or someone authorized on the account."],["Third party","I understand you’re calling as a third party regarding this account. Can you please provide the policy number and the line of business you’re calling about?"],["Dissatisfied caller","I understand your concern. To protect your account information, I’m unable to provide policy-specific information until the account can be successfully verified. Please let me know the reason for your call so I can determine how we can best assist you."],["Verified","Thank you for providing the business details. I have successfully verified your account. How may I assist you today?"]],n:["Don’t read identifiers from Epic to the caller."],e:"GCAL"},
{id:"documents",c:3,l:"H",t:"Document, certificate or ID card request",k:"certificate coi policy copy declarations endorsements id cards evidence of insurance send documents",s:"Verified callers can request documents. Get the delivery email.",
f:["Can send: policies, endorsements, audit documents, cancellation and reinstatement notices, certificates, auto ID cards, evidence of insurance.","Can provide: current balance, due date, payment history, active policies, carriers, effective and expiration dates.","Certificate requests (from notes, verify): Certificates_CL@acrisure.com.","Servicing: P&C Servicer 2 = Carrier Service Center means that policy is carrier serviced; warm transfer. Check each policy; accounts can be split."],p:["Verify.","Check servicing responsibility per policy.","Collect email and document."],
q:[["Email","Can you please provide the email address where the document should be sent?"],["Close","Thank you. I have documented your request and the email address for delivery. Is there anything else I can assist you with today?"],["Certificate request","I can send that to an authorized contact at [Business Name]. Are you listed on the account, or should I confirm with the business?"],["Carrier unavailable","A carrier representative isn’t available right now. I’ve documented your request and noted the follow-up needed, so you won’t need to repeat yourself."]],n:["Don’t send to unverified callers."],e:"GCAL"}
];
var P={
home:"Home",universal:"Call flow and universal scripts",codes:"Epic codes and glossary",avoid:"Phrases to avoid",escalation:"Escalation and routing matrix",status:"Policy status guide",facts:"FACTS call framework",privacy:"Privacy and documentation",fnolform:"FNOL form guide",notes:"Epic notes guide",spiels:"Spiel library",index:"All pages (A–Z)",about:"About and credits"};
var $=function(i){return document.getElementById(i)};
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;")}
function nav(cur){var h='<a href="#home" data-r="1">🎲 Random article</a><h3>Reference</h3>';for(var k in P)h+='<a href="#'+k+'"'+(cur==k?' class="on"':'')+'>'+P[k]+'</a>';
CATS.forEach(function(c,i){h+='<h3><a href="#cat-'+i+'">'+esc(c)+'</a></h3>';D.forEach(function(d){if(d.c==i)h+='<a href="#d-'+d.id+'"'+(cur=='d-'+d.id?' class="on"':'')+'><span class="dot '+d.l+'"></span>'+esc(d.t)+'</a>'})});$('nav').innerHTML=h}
function badges(d){return '<span class="badge '+d.l+'">'+L[d.l]+'</span><span class="badge c">'+CATS[d.c]+'</span><span class="badge c">Epic: '+esc(d.e)+'</span>'}
function card(d){return '<a class="card" href="#d-'+d.id+'"><span class="badge '+d.l+'">'+L[d.l]+'</span><b>'+esc(d.t)+'</b><span class="t">'+esc(d.s)+'</span></a>'}
function list(a,o){return (o?'<ol>':'<ul>')+a.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+(o?'</ol>':'</ul>')}
function driver(d){var h='<div class="crumb"><a href="#home">Home</a> › <a href="#cat-'+d.c+'">'+esc(CATS[d.c])+'</a> › '+esc(d.t)+'</div><h2>'+esc(d.t)+'</h2><div class="info"><div class="ih">Quick facts</div><dl><dt>Category</dt><dd>'+esc(CATS[d.c])+'</dd><dt>Action</dt><dd><span class="badge '+d.l+'">'+L[d.l]+'</span></dd><dt>Epic code</dt><dd>'+esc(d.e)+'</dd><dt>Ready-made spiels</dt><dd>'+d.q.length+'</dd></dl></div><p class="lead">'+esc(d.s)+'</p><div class="toc"><b>Contents</b><ol>'+[["s1","Facts to know"],["s2","Steps"],["s3","What to say"],["s4","Never do or say"],["s5","See also"]].map(function(x){return '<li><a data-j="'+x[0]+'" href="#d-'+d.id+'">'+x[1]+'</a></li>'}).join('')+'</ol></div><h3 id="s1">Facts to know</h3><div class="box">'+list(d.f)+'</div><h3 id="s2">Steps</h3><div class="box">'+list(d.p,1)+'</div><h3 id="s3">What to say</h3>';
d.q.forEach(function(x,i){h+='<div class="box say"><button class="copy" data-t="'+esc(x[1]).replace(/"/g,"&quot;")+'">Copy</button><b class="l">'+esc(x[0])+'</b>“'+esc(x[1])+'”</div>'});
h+='<h3 id="s4">Never do or say</h3><div class="box no">'+list(d.n)+'</div>';
h+='<h3 id="s5">See also</h3><div class="grid">'+D.filter(function(x){return x.c==d.c&&x.id!=d.id}).slice(0,3).map(card).join('')+'</div>';return h}
var PAY="https://www.paypal.com/paypalme/LeighNCR";function foot(){return '<div class="foot"><p><b>Compiled by Leigh Jannah Ramos.</b> Free for customer service teams to use as a shared knowledge base. This is a training aid: always confirm against your current SOPs and licensed team direction.</p><a class="don" href="'+PAY+'" target="_blank" rel="noopener">Support the author on PayPal</a></div>'}
var T={
home:function(){return '<h2>Welcome to the Commercial Lines Agent Wiki</h2><p class="lead">'+D.length+' articles and '+Object.keys(P).length+' reference pages. Search any call driver, spiel or fact. Every driver is marked Handle, Route or Stop. Core rule: verify, state facts, stop at licensed questions (don’t answer), document, then warm transfer.</p><div class="box say"><b class="l">Remember FACTS</b>First verify, Ask the call purpose, Capture neutrally, Tell the boundary, Summarize and send. <a href="#facts">Full framework</a></div><div class="box"><span class="badge H">Handle</span> you can answer with verified facts. <span class="badge R">Route</span> warm transfer or hand off. <span class="badge S">Stop</span> a stop point: don’t answer it. Document it, then warm transfer or route to the licensed team, appropriate team or Account Manager.</div>'+CATS.map(function(c,i){return '<h3>'+esc(c)+'</h3><div class="grid">'+D.filter(function(d){return d.c==i}).map(card).join('')+'</div>'}).join('')},
universal:function(){return '<h2>Call flow and universal scripts</h2><p class="lead">Greeting → locate account → verify authorization (two identifiers) → determine servicing responsibility → answer or route → document in Epic → close.</p><h3>Greeting</h3><div class="box say"><button class="copy" data-t="Thank you for calling Acrisure. This is [name]. Can I please have the business name you are calling about?">Copy</button>“Thank you for calling Acrisure. This is [name]. Can I please have the business name you are calling about?”</div><div class="box say"><b class="l">Hold</b>“Please hold while I pull your account up in our system.”</div><h3>Verify the caller</h3><div class="box say"><button class="copy" data-t="I have successfully pulled your account up in our system. For verification, I’ll need to confirm a couple more details. Can you please provide [identifier]?">Copy</button><b class="l">After locate</b>“I have successfully pulled your account up in our system. For verification, I’ll need to confirm a couple more details. Can you please provide [identifier]?”</div><div class="box say"><button class="copy" data-t="May I know the business name and the mailing address?">Copy</button><b class="l">Business</b>“May I know the business name and the mailing address?”</div><div class="box say"><button class="copy" data-t="Great, and who am I speaking with and your role with [Business Name]?">Copy</button><b class="l">Caller</b>“Great, and who am I speaking with and your role with [Business Name]?”</div><h3>Handoffs</h3><div class="box say">“Let me connect you with the appropriate team so they can assist you further.”</div><div class="box say"><b class="l">Coverage question</b>“That’s an important question. Let me connect you with a licensed agent who can review your specific coverage.”</div><div class="box say"><b class="l">Recommendation</b>“That’s a coverage recommendation, so I’ll have a licensed agent walk you through your options.”</div><h3>Warm transfer steps</h3><div class="box">'+list(["Tell the caller they will be connected with the carrier.","Initiate the transfer and stay on the line.","Introduce the caller, reason and policy number.","Confirm the representative can assist, then disconnect.","Create the GCAL activity."],1)+'</div><div class="box warn"><b class="l">Rule update</b>Don’t give out the carrier’s or Account Manager’s phone number. Warm transfer instead. For a direct bill payment, find the carrier’s number in LastPass.</div><h3>Closing</h3><div class="box say">“To recap, we have [action]. Your request has been [resolved/transferred/escalated], and [next steps]. Is there anything else I can assist you with today? Thank you for calling Acrisure. We appreciate the opportunity to support your business.”</div><h3>Always document</h3><div class="box">'+list(["Caller and authorization status","Question asked and information provided","Transfer or route destination","Follow-up expectation and dates mentioned"])+'</div><h3>Callers you will meet</h3><div class="box">Risk managers, business owners, office managers, CFOs, controllers, bookkeepers. Bookkeepers and admin staff generally have limited access.</div>'},
codes:function(){return '<h2>Epic codes and glossary</h2><div class="tw"><table><tr><th>Code</th><th>Description</th><th>Use when / Owner</th></tr><tr><td>GCAL</td><td>General Inquiry Call</td><td>General inquiries, transfers, verification issues. Document caller, reason, verification status, action taken.</td></tr><tr><td>CBIQ</td><td>CL Billing Inquiry</td><td>Payments, balances, due dates, invoices, past-due, pending cancel. Escalate cancelled / In-Process to P&C Servicer 1 as Urgent.</td></tr><tr><td>CCRF</td><td>CL Claim Notification / Inquiry (FNOL)</td><td>Every first notice of loss and claim inquiry. Priority Urgent; Owner *CCLP (or P&C Servicer 1 for WC / Professional / Management Liability / Signature).</td></tr><tr><td>CCN1</td><td>CL – Carrier Notice of Cancellation (*CNOC)</td><td>Carrier-driven: notice of cancellation for non-compliance (underwriting, inspection, audit not completed). Owner *CNOC / P&C Servicer 1.</td></tr><tr><td>CCN2</td><td>CL – Notice of Cancellation for Non-Payment (*CNOC)</td><td>Carrier-driven: non-payment (Direct Bill or Premium Finance). Owner *CNOC / P&C Servicer 1.</td></tr><tr><td>CCN3</td><td>CL – Client Request for Cancellation (*CCCR)</td><td>Insured-driven: client requests cancellation (sold business, replaced coverage, etc.). Owner *CCCR / P&C Servicer 1.</td></tr><tr><td>ACLM</td><td>Claim activity</td><td>Kept open until the carrier closes the claim.</td></tr></table></div><h3>Cancellation activity quick pick</h3><div class="box">'+list(["CCN1 – Carrier notice, non-compliance","CCN2 – Carrier notice, non-payment","CCN3 – Client requested cancellation"])+'</div><h3>Glossary</h3><div class="box">'+list(["FNOL: first notice of loss.","NOC: notice of cancellation.","Audit: carrier review confirming premium inputs were accurate.","Agency bill: Acrisure invoices the client. Direct bill: client pays the carrier.","Statement of No Loss: signed statement that no loss occurred during a lapse. Never explain, validate, collect or advise.","PFA: premium finance agreement (IPFS or First Insurance Funding). Look under Access > Attachments.","P&C Servicer 1: account manager escalation path.","P&C Servicer 2 = Carrier Service Center flag — check at both account and policy level; accounts can be split.","Signature vs Select: client service segments that change claim and billing routing. Signature → route to P&C Servicer 1 / Claims name."])+'</div>'},
avoid:function(){var r=[["This should be covered.","That is a licensed coverage question, so I’m going to connect you with the appropriate licensed team member."],["You should file the claim.","I can document the information available now and connect you with the right team or carrier contact for next steps."],["The carrier will pay this.","The carrier will review the claim and determine next steps."],["This will not impact your premium.","Premium impact questions need to be reviewed by the licensed Acrisure team."],["You can reopen the claim.","Questions about reopening or disputing a claim need to be reviewed by the licensed Acrisure team."],["Don’t worry, this will be handled.","I’m sorry to hear that happened. I’ll make sure the information is documented clearly and routed to the right team."]];return '<h2>Phrases to avoid</h2><div class="tw"><table><tr><th>Avoid</th><th>Use instead</th></tr>'+r.map(function(x){return '<tr><td>“'+x[0]+'”</td><td>“'+x[1]+'”</td></tr>'}).join('')+'</table></div><h3>Never</h3><div class="box no">'+list(["Interpret policy language or make coverage determinations.","Guarantee coverage, claim outcomes, audit results or reinstatement.","Quote refunds or return premium.","Confirm certificate validity after a lapse.","Disclose information to unverified callers.","Leave claim details in voicemail.","Give out a carrier or Account Manager phone number. Warm transfer instead."])+'</div>'},
escalation:function(){return '<h2>Escalation and routing matrix</h2><div class="tw"><table><tr><th>Trigger</th><th>Route</th></tr><tr><td>Any claims transfer when the account has a P&C Claims name</td><td>That P&C Claims person instead of P&C Servicer 1</td></tr><tr><td>Payment, agency bill</td><td>P&C Servicer 1</td></tr><tr><td>Payment, direct bill</td><td>Carrier (find the number in LastPass)</td></tr><tr><td>New claim, no licensed questions or concerns</td><td>Carrier</td></tr><tr><td>New claim, licensed questions or concerns</td><td>Licensed team</td></tr><tr><td>Caller not a listed contact, third party, or dissatisfied (claims)</td><td>Account Manager (P&C Servicer 1)</td></tr><tr><td>Estimated loss $100k or more, litigation, fatality</td><td>Appropriate team (CCL workgroup); notify the Account Manager</td></tr><tr><td>Workers’ Comp or Professional / Management Liability</td><td>P&C Servicer 1</td></tr><tr><td>Signature client</td><td>Account Manager (P&C Servicer 1)</td></tr><tr><td>Large loss ($100k+), litigation, fatality</td><td>Account Manager (P&C Servicer 1), with the completed FNOL</td></tr><tr><td>Carrier non-responsiveness, client complaints</td><td>Account Manager (P&C Servicer 1)</td></tr><tr><td>Stage Cancelled or In-Process</td><td>CBIQ to P&C Servicer 1</td></tr><tr><td>Cancellation, lapse or audit question</td><td>P&C Servicer 1</td></tr><tr><td>Servicer 2 = Carrier Service Center</td><td>Warm transfer to carrier</td></tr></table></div><div class="box warn">Document the trigger and escalate the same day.</div>'},
status:function(){return '<h2>Policy status guide</h2><div class="tw"><table><tr><th>Status</th><th>Meaning</th><th>Your action</th></tr><tr><td>Current / upcoming</td><td>Not yet late</td><td>Facts, then warm transfer</td></tr><tr><td>Grace period</td><td>Past due, not cancelled</td><td>State deadline; transfer</td></tr><tr><td>Pending cancellation</td><td>Notice sent, not yet effective</td><td>State notice date; transfer</td></tr><tr><td>Lapsed / cancelled</td><td>Coverage ended</td><td>Reinstatement request, not guaranteed; route</td></tr><tr><td>Beyond window</td><td>Past carrier’s window</td><td>Likely new application; licensed agent</td></tr></table></div><h3>Current vs audit</h3><div class="box">Current premium is ongoing billing. Audit balance is a prior-period adjustment.</div>'},
facts:function(){return '<h2>FACTS call framework</h2><p class="lead">A five-step habit for every claims call.</p><div class="box">'+list(["First verify: two identifiers before any detail.","Ask the call purpose: new loss, claim status, lawsuit or legal item, or claimant.","Capture neutrally: write “caller stated…” and no fault or coverage language.","Tell the boundary: say what you can do and route what is licensed.","Summarize and send: recap the next step and route or email."],1)+'</div><div class="box say"><b class="l">Claim documents</b>If the client wants to send documents, email ClaimInformation_CL@Acrisure.com.</div>'},
privacy:function(){return '<h2>Privacy and documentation</h2><h3>Privacy compliance</h3><div class="box no">'+list(["Do not confirm information when the account or caller can’t be sufficiently verified.","Third party or claimant: collect factual contact and incident information but don’t disclose the client’s policy or claim details.","Never leave claim details in voicemail; use a privacy-safe callback message."])+'</div><h3>Automatic escalation</h3><div class="box">'+list(["Estimated loss $100k or greater","Litigation or lawsuit","Fatality","Workers’ Compensation (and Professional / Management Liability)"])+'</div><h3>Documentation details</h3><div class="box"><b>Lawsuit, summons or demand letter:</b> type, date received, sender, response deadline.<br><b>Claimant attorney calls:</b> name, law firm, contact information, representation letter.<br><b>Large loss or significant reserve:</b> factual severity, injuries or unsafe conditions, affected operations, carrier information, reserve change stated.</div><h3>Unclear questions</h3><div class="box warn">Do not answer. Document the exact question and transfer to the licensed team.</div><h3>Callback opening</h3><div class="box say">“This call is being monitored or recorded for quality and training purposes.”</div>'},
fnolform:function(){return '<h2>FNOL form guide</h2><p class="lead">Capture the caller’s description and known facts only. Don’t determine coverage, assign fault or promise outcomes. Route promptly.</p><div class="tw"><table><tr><th>Section</th><th>Fields</th></tr><tr><td>Insured and caller</td><td>Date of call, insured/business name, Epic account or client code, caller name, phone</td></tr><tr><td>Line of business</td><td>Commercial Auto, Property, GL, Workers’ Comp, Professional / Management Liability, Other</td></tr><tr><td>Loss details</td><td>Date, time, location</td></tr><tr><td>Auto</td><td>Year/make/model, VIN, driver, vehicle location, description of vehicle damage</td></tr><tr><td>Property</td><td>Location address, type of damage, property secured (yes/no/unknown)</td></tr><tr><td>General Liability</td><td>Injured party/claimant name and contact, description of injury or incident</td></tr><tr><td>Other</td><td>Other / additional loss information</td></tr></table></div>'},
notes:function(){return '<h2>Epic notes guide: payments and reinstatement</h2><p class="lead">What to capture in the Epic activity notes on payment and reinstatement calls.</p><div class="tw"><table><tr><th>Capture in notes</th><th>Examples / detail needed</th></tr><tr><td><b>Caller verification</b></td><td>Business name, mailing address, caller name, caller role, authorization status.</td></tr><tr><td><b>Policy status</b></td><td>Current, grace period, pending cancellation, cancelled/lapsed, or past-window. Include dates.</td></tr><tr><td><b>Policy involved</b></td><td>GL, BOP, WC, Commercial Auto, Professional Liability, etc.</td></tr><tr><td><b>Payment/balance information discussed</b></td><td>Amount due, due date, audit balance vs current premium, payment path provided.</td></tr><tr><td><b>Client concern</b></td><td>Reinstatement, inability to pay, audit dispute, claims-made gap, lender issue, certificate issue.</td></tr><tr><td><b>Safe expectation statement</b></td><td>Document that reinstatement/coverage/certificate/lender outcome was not promised.</td></tr><tr><td><b>Routing path</b></td><td>Carrier, finance company, licensed agent, audit review, servicing team, or applicable internal queue.</td></tr><tr><td><b>Action completed</b></td><td>Warm transfer, message sent, activity created, callback requested, documents provided, or client instructed to contact carrier.</td></tr></table></div><h3>Example note</h3><div class="box say"><button class="copy" data-t="Spoke with [caller name], [role], regarding [reason for call]. Verified business name, mailing address, caller name and role; authorization confirmed. [GL] policy is [pending cancellation, notice date]. Discussed amount due [amount], due date [date], current premium vs audit balance. Client concern: [reinstatement]. No outcome was promised for reinstatement, coverage, certificates or lender. Routed to [P&C Servicer 1]. Action: warm transfer completed.">Copy</button><b class="l">Template, edit the brackets</b>Spoke with [caller name], [role], regarding [reason for call]. Verified business name, mailing address, caller name and role; authorization confirmed. [GL] policy is [pending cancellation, notice date]. Discussed amount due [amount], due date [date], current premium vs audit balance. Client concern: [reinstatement]. No outcome was promised for reinstatement, coverage, certificates or lender. Routed to [P&C Servicer 1]. Action: warm transfer completed.</div><div class="box warn">Always document the safe expectation statement: never promise reinstatement, coverage, certificate or lender outcomes.</div>'},
spiels:function(){var h='<h2>Spiel library</h2><p class="lead">Every ready-to-use script in one place. Click Copy to use it.</p>';CATS.forEach(function(c,i){h+='<h3>'+esc(c)+'</h3>';D.filter(function(d){return d.c==i}).forEach(function(d){h+='<p><a href="#d-'+d.id+'"><b>'+esc(d.t)+'</b></a></p>';d.q.forEach(function(x){h+='<div class="box say"><button class="copy" data-t="'+esc(x[1]).replace(/"/g,'&quot;')+'">Copy</button><b class="l">'+esc(x[0])+'</b>“'+esc(x[1])+'”</div>'})})});return h},
index:function(){var a=[];for(var k in P)a.push([P[k],k,'Reference']);D.forEach(function(d){a.push([d.t,'d-'+d.id,CATS[d.c]])});a.sort(function(x,y){return x[0].localeCompare(y[0])});return '<h2>All pages (A–Z)</h2><div class="tw"><table><tr><th>Page</th><th>Section</th></tr>'+a.map(function(x){return '<tr><td><a href="#'+x[1]+'">'+esc(x[0])+'</a></td><td>'+esc(x[2])+'</td></tr>'}).join('')+'</table></div>'},
about:function(){return '<h2>About this wiki</h2><p class="lead">A shared knowledge base for Commercial Lines customer service agents, built from SOPs, job aids, scripts and reviewer notes.</p><h3>How to use it</h3><div class="box">'+list(["Type a call driver, phrase or code in the search bar (for example “reinstatement” or “CCRF”).","Open an article for quick facts, steps, ready-to-copy spiels and what never to say.","Use Random article to practice, and All pages (A–Z) to browse everything.","Colour key: Handle means you can answer with verified facts, Route means warm transfer or hand off, Stop means don’t answer: document it, then warm transfer or route."])+'</div><h3>Sources</h3><div class="box">'+list(["CL Voice SOPs: Claims, Payments and Reinstatement, Caller Authentication.","FNOL intake form, call type reference guides, job aids and scripts.","Reviewer notes. Items marked “verify” came from notes only."])+'</div><h3>Disclaimer</h3><div class="box warn">This is an unofficial training aid, not legal, coverage or licensed advice. If it conflicts with your current SOP, compliance guidance or licensed team direction, follow those instead.</div><h3>Credits and support</h3><div class="box">Compiled and maintained by <b>Leigh Jannah Ramos</b>. Free to use. If it helps you, you can optionally support the author.<br><br><a class="don" href="'+PAY+'" target="_blank" rel="noopener">Support the author on PayPal</a></div>'}};
function hay(d){return (d.t+' '+d.k+' '+d.s+' '+d.e+' '+d.f.join(' ')+' '+d.q.map(function(x){return x[0]+' '+x[1]}).join(' ')+' '+d.n.join(' ')+' '+CATS[d.c]).toLowerCase()}
function score(d,words){var s=hay(d),sc=0;words.forEach(function(w){if(d.t.toLowerCase().indexOf(w)>-1)sc+=8;if(d.k.toLowerCase().indexOf(w)>-1)sc+=5;if(d.e.toLowerCase().indexOf(w)>-1)sc+=6;if(s.indexOf(w)>-1)sc+=1});return sc}
function hit(d,words){var s=hay(d);return words.every(function(w){return s.indexOf(w)>-1})}
function hl(text,words){var t=esc(text);words.forEach(function(w){if(!w)return;var re=new RegExp('('+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi');t=t.replace(re,'<mark>$1</mark>')});return t}
function cardS(d,words){return '<a class="card" href="#d-'+d.id+'"><span class="badge '+d.l+'">'+L[d.l]+'</span><span class="badge c">'+esc(d.e)+'</span><b>'+hl(d.t,words)+'</b><span class="t">'+hl(d.s,words)+'</span></a>'}
function search(q){q=q.trim().toLowerCase();if(!q){route();return}var words=q.split(/\s+/).filter(Boolean);var r=D.filter(function(d){return hit(d,words)}).map(function(d){return {d:d,sc:score(d,words)}}).sort(function(a,b){return b.sc-a.sc}).map(function(x){return x.d});
var refs=[];for(var k in P){if(k==='home')continue;var label=P[k].toLowerCase();if(words.every(function(w){return label.indexOf(w)>-1||k.indexOf(w)>-1}))refs.push({k:k,t:P[k]})}
nav('');var html='<h2>Search results</h2><p class="lead">'+r.length+' call driver'+(r.length===1?'':'s')+(refs.length?' · '+refs.length+' reference page'+(refs.length===1?'':'s'):'')+' for “'+esc(q)+'”</p>';
if(refs.length){html+='<h3>Reference pages</h3><div class="grid">'+refs.map(function(x){return '<a class="card" href="#'+x.k+'"><b>'+hl(x.t,words)+'</b><span class="t">Reference</span></a>'}).join('')+'</div>'}
html+=r.length?'<h3>Call drivers</h3><div class="grid">'+r.map(function(d){return cardS(d,words)}).join('')+'</div>':'<div class="box warn">No call-driver match. If unsure whether a question needs a license, do not answer: document it and transfer.</div>';
$('main').innerHTML=html}
function route(){var h=location.hash.slice(1)||'home';if(!$('q').matches(':focus'))$('q').value='';var m=$('main');if(h.indexOf('d-')==0){var d=D.filter(function(x){return 'd-'+x.id==h})[0];if(d){m.innerHTML=driver(d)+foot();nav(h);window.scrollTo(0,0);return}}
if(h.indexOf('cat-')==0){var ci=+h.slice(4);if(CATS[ci]){m.innerHTML='<div class="crumb"><a href="#home">Home</a> › '+esc(CATS[ci])+'</div><h2>Category: '+esc(CATS[ci])+'</h2><div class="grid">'+D.filter(function(x){return x.c==ci}).map(card).join('')+'</div>'+foot();nav(h);window.scrollTo(0,0);return}}
if(T[h]){m.innerHTML=(h=='home'?'':'<div class="crumb"><a href="#home">Home</a> › '+esc(P[h]||'')+'</div>')+T[h]()+foot();nav(h)}else{m.innerHTML=T.home()+foot();nav('home')}window.scrollTo(0,0)}
var searchTimer; $('q').addEventListener('input',function(){var v=this.value;clearTimeout(searchTimer);searchTimer=setTimeout(function(){search(v)},120)});
$('q').addEventListener('keydown',function(e){if(e.key==='Escape'){this.value='';route();this.blur()}});
$('main').addEventListener('click',function(e){var b=e.target.closest('.copy');if(b){try{navigator.clipboard.writeText(b.getAttribute('data-t'));b.textContent='Copied';setTimeout(function(){b.textContent='Copy'},1200)}catch(x){b.textContent='Select text'}}});
$('tg').addEventListener('click',function(){$('nav').classList.toggle('open')});
document.addEventListener('click',function(e){var j=e.target.closest('[data-j]');if(j){e.preventDefault();var t=document.getElementById(j.getAttribute('data-j'));if(t)t.scrollIntoView({behavior:'smooth',block:'start'});return}var r=e.target.closest('[data-r]');if(r){e.preventDefault();var x=D[Math.floor(Math.random()*D.length)];location.hash='d-'+x.id}});
window.addEventListener('hashchange',route);route();
